function describeRequestDevice(value: string | string[] | undefined) { const userAgent = (Array.isArray(value) ? value[0] : value || "").toLowerCase(); if (userAgent.includes("iphone")) return "iPhone"; if (userAgent.includes("ipad")) return "iPad"; if (userAgent.includes("android")) return userAgent.includes("mobile") ? "هاتف Android" : "جهاز Android"; if (userAgent.includes("mac os")) return "Mac"; if (userAgent.includes("windows")) return "Windows"; if (userAgent.includes("linux")) return "Linux"; return "متصفح جديد"; }

async function persistAvatar(scope: "teacher" | "student", id: number, imageDataUrl: string) {
  const match = /^data:image\/(png|jpeg|jpg|webp);base64,(.+)$/.exec(imageDataUrl);
  if (!match) throw new TRPCError({ code: "BAD_REQUEST", message: "صيغة الصورة غير مدعومة." });
  const subtype = match[1] === "jpg" ? "jpeg" : match[1];
  const image = Buffer.from(match[2], "base64");
  if (!image.length || image.length > 2_500_000) throw new TRPCError({ code: "PAYLOAD_TOO_LARGE", message: "يجب ألا يتجاوز حجم الصورة 2.5 ميجابايت." });
  return storagePut(`${scope}-avatars/${id}/profile.${subtype}`, image, `image/${subtype}`);
}
